  unsigned int keycode;
} XKeyEvent;

typedef union {
  int type;
  struct {
    int type;
  } xany;
  XKeyEvent xkey;
  struct {
    int type;
    unsigned int button;
    int x, y;
    unsigned int state;
  } xbutton;
  struct {
    int type;
    int x, y;
    unsigned int state;
  } xmotion;
} XEvent;

