1219	static void analogtv_add_signal(const analogtv *it, const analogtv_reception *rec, unsigned start, unsigned end, int ec)
1220	{
1221	  analogtv_input *inp=rec->input;
1222	  float *ps=it->rx_signal + start;
1223	  float *pe=it->rx_signal + end;
1224	  float *p=ps;
1225	  signed char *ss=&inp->signal[0][0];
1226	  signed char *se=&inp->signal[0][0] + ANALOGTV_SIGNAL_LEN;
1227	  signed char *s=ss + ((start + (unsigned)rec->ofs) % ANALOGTV_SIGNAL_LEN);
1228	  signed char *s2;
1229	  int i;
1230	  float level=rec->level;
1231	  float hfloss=rec->hfloss;
1232	  unsigned int fastrnd=rnd_seek(FASTRND_A, FASTRND_C, it->random1, start);
1233	  float dp[5];
1234	
1235	  const float noise_decay = 0.99995f;
1236	  float noise_ampl = 1.3f * powf(noise_decay, start);
1237	
1238	  if (ec > end)
1239	    ec = end;
1240	
1241	  /* assert((se-ss)%4==0 && (se-s)%4==0); */
1242	
1243	  for (i = start; i < ec; i++) { /* Sometimes start > ec. */
1244	
1245	    /* Do a big noisy transition. We can make the transition noise of
1246	       high constant strength regardless of signal strength.
1247	
1248	       There are two separate state machines. here, One is the noise
1249	       process and the other is the
1250	
1251	       We don't bother with the FIR filter here
1252	    */
1253	
1254	    float sig0=(float)s[0];
1255	    unsigned int fastrnd_offset = fastrnd - 0x7fffffff;
1256	    float noise = (fastrnd_offset <= INT_MAX ? (int)fastrnd_offset : -1 - (int)(UINT_MAX - fastrnd_offset)) * (50.0f/(float)0x7fffffff);
1257	    fastrnd = (fastrnd*FASTRND_A+FASTRND_C) & 0xffffffffu;
1258	
1259	    p[0] += sig0 * level * (1.0f - noise_ampl) + noise * noise_ampl;
1260	
1261	    noise_ampl *= noise_decay;
1262	
1263	    p++;
1264	    s++;
1265	    if (s>=se) s=ss;
1266	  }
1267	
1268	  dp[0]=0.0;
1269	  s2 = s;
1270	  for (i=1; i<5; i++) {
1271	    s2 -= 4;
1272	    if (s2 < ss)
1273	      s2 += ANALOGTV_SIGNAL_LEN;
1274	    dp[i] = (float)((int)s2[0]+(int)s2[1]+(int)s2[2]+(int)s2[3]);
1275	  }
1276	
1277	  assert(p <= pe);
1278	  assert(!((pe - p) % 4));
1279	  while (p != pe) {
1280	    float sig0,sig1,sig2,sig3,sigr;
1281	
1282	    sig0=(float)s[0];
1283	    sig1=(float)s[1];
1284	    sig2=(float)s[2];
1285	    sig3=(float)s[3];
1286	
1287	    dp[0]=sig0+sig1+sig2+sig3;
1288	
1289	    /* Get the video out signal, and add some ghosting, typical of RF
1290	       monitor cables. This corresponds to a pretty long cable, but
1291	       looks right to me.
1292	    */
1293	
1294	    sigr=(dp[1]*rec->ghostfir[0] + dp[2]*rec->ghostfir[1] +
1295	          dp[3]*rec->ghostfir[2] + dp[4]*rec->ghostfir[3]);
1296	    dp[4]=dp[3]; dp[3]=dp[2]; dp[2]=dp[1]; dp[1]=dp[0];
