1299	    p[1] += (sig1+sigr + sig3*hfloss) * level;
1300	    p[2] += (sig2+sigr + sig0*hfloss) * level;
1301	    p[3] += (sig3+sigr + sig1*hfloss) * level;
1302	
1303	    p += 4;
1304	    s += 4;
