    for (int i = 0; i < GLPROF_SLOTS; i++)
      Serial.printf(" n%s=%.0f", glshim_prof_names[i],
                    (float)glshim_prof_calls[i] / glshim_prof_frames);
    Serial.printf("\n");
  }
#endif

