1770	  it->recs = recs;
1771	  it->rec_count = rec_count;
1772	  threadpool_run(&it->threads, analogtv_thread_add_signals);
1773	  threadpool_wait(&it->threads);
1774	
1775	  it->channel_change_cycles=0;
1776	
1777	  /* rx_signal has an extra 2 lines at the end, where we copy the
1778	     first 2 lines so we can index into it while only worrying about
1779	     wraparound on a per-line level */
1780	  memcpy(&it->rx_signal[ANALOGTV_SIGNAL_LEN],
1781	         &it->rx_signal[0],
1782	         2*ANALOGTV_H*sizeof(it->rx_signal[0]));
1783	
1784	  /* Repeat for signal_subtotals. */
1785	
1786	  memcpy(&it->signal_subtotals[ANALOGTV_SIGNAL_LEN / ANALOGTV_SUBTOTAL_LEN],
1787	         &it->signal_subtotals[0],
1788	         (2*ANALOGTV_H/ANALOGTV_SUBTOTAL_LEN)*sizeof(it->signal_subtotals[0]));
1789	
1790	  analogtv_sync(it); /* Requires the add_signals be complete. */
