  ".background:	        black",
  ".foreground:	        white",
  "*delay:	        5",
  "*grabDesktopImages:  False",   /* HAVE_JWXYZ */
  "*chooseRandomImages: True",    /* HAVE_JWXYZ */
  "*colorbarsOnly:      False",
