/* Shim replacement for xscreensaver's utils/ximage-loader.h. Not derived from
 * xscreensaver code.
 *
 * Upstream decodes a PNG. The device has no decoder, so the "image data" here
 * is a raw blob made on the Mac by tools/make_logo_blob.py:
 *
 *   bytes 0-3          the characters "565M"
 *   bytes 4-5          width, unsigned 16-bit little-endian
 *   bytes 6-7          height, unsigned 16-bit little-endian
 *   next width*height  pixels, row by row, each RGB565 as 16-bit little-endian
 *   remainder          mask, row by row, each row padded to whole bytes,
 *                      most significant bit first; 1 = draw the pixel
 *
 * The blob size must match its width and height exactly.
 *
 * A "565Z" blob (make_logo_blob.py --deflate) has the same eight-byte header,
 * then the pixels and mask as one zlib stream, which must unpack to exactly
 * that size. It is inflated into a temporary buffer while the image loads. */
#ifndef XSHIM_XIMAGE_LOADER_H
#define XSHIM_XIMAGE_LOADER_H
#include "x11shim/xshim.h"
#ifdef __cplusplus
extern "C" {
#endif
/* Returns a colour pixmap, and writes its size and a depth-1 mask pixmap
 * through the pointers. Returns None (and writes zeros and None) when the
 * blob is not valid or memory runs out. The caller frees both pixmaps. Any of
 * the three pointers may be NULL (xmatrix passes no mask, and none is made). */
Pixmap image_data_to_pixmap(Display *, Window, const unsigned char *data,
                            unsigned long size, int *width_ret,
                            int *height_ret, Pixmap *mask_ret);
/* The image as a 32-bit XImage of RGBA bytes (alpha 255 where the mask is set,
 * 0 where not), upside down, row 0 being the bottom, as upstream gives it for
 * glTexImage2D. NULL for a bad blob or no memory; free it with XDestroyImage. */
XImage *image_data_to_ximage(Display *, Visual *, const unsigned char *data,
                             unsigned long size);
/* Upstream reads an image file. The device has no filesystem for hacks and no
 * decoder, so this always returns NULL, and a hack that loads an optional
 * picture carries on without one. */
XImage *file_to_ximage(Display *, Visual *, const char *filename);
#ifdef __cplusplus
}
#endif
#endif
/* Shim replacement for xscreensaver's utils/grabclient.h. Not derived from
 * xscreensaver code.
 *
 * Upstream loads a picture of the desktop or a random image file into a
 * drawable, a little at a time. The device has neither, so loading finishes at
 * once. With no picture set (xshim_set_grab_image) nothing is loaded and
 * Boxfit's optional `grab` mode would colour its boxes from the window as it
 * stands; with one, the picture is painted over the target first. */
#ifndef XSHIM_GRABCLIENT_H
#define XSHIM_GRABCLIENT_H
#include "x11shim/xshim.h"
#ifdef __cplusplus
extern "C" {
#endif
typedef struct async_load_state async_load_state;
/* Returns NULL (finished) at once and draws nothing; a file name asked for is
 * NULL and a geometry asked for is all zero. */
async_load_state *load_image_async_simple(async_load_state *, Screen *,
                                          Window top_level, Drawable target,
                                          char **filename_ret,
                                          XRectangle *geometry_ret);
/* Gives loading a picture to put up: an image blob as described in
 * ximage-loader.h, which must outlive its use. The next load that starts
 * (state NULL) paints it over its target, scaled to cover and cropped evenly
 * at the sides, as a grabbed screen would be; NULL (the default) goes back to
 * loading nothing. */
void xshim_set_grab_image(const unsigned char *blob, unsigned long size);
#ifdef __cplusplus
}
#endif
#endif
  uint16_t *row = (uint16_t *)malloc((size_t)c->w * sizeof(uint16_t));
  int *column = (int *)malloc((size_t)c->w * sizeof(int));
  if (row && column) {
    for (int x = 0; x < c->w; x++) {
      const int from = (int)floorf(((float)x + 0.5f - left) / scale);
      column[x] = from < 0 ? 0 : from >= w ? w - 1 : from;
    }
    for (int y = 0; y < c->h; y++) {
      int line = (int)floorf(((float)y + 0.5f - top) / scale);
      line = line < 0 ? 0 : line >= h ? h - 1 : line;
      const uint16_t *from = pm->canvas.px + (int64_t)line * w;
      for (int x = 0; x < c->w; x++) row[x] = from[column[x]];
      canvas_paste_rect(c, 0, y, c->w, 1, row);
    }
  }
  free(row);
  free(column);
  XFreePixmap(dpy, image);
}

async_load_state *load_image_async_simple(async_load_state *state, Screen *screen,
                                          Window top_level, Drawable target,
                                          char **filename_ret,
                                          XRectangle *geometry_ret) {
  (void)screen;
  if (filename_ret) *filename_ret = NULL;
  if (geometry_ret) *geometry_ret = (XRectangle){0, 0, 0, 0};
  if (!state && g_grab_blob) paint_grab_image(xshim_current_display(), top_level, target);
  return NULL;
}

