s = s.rstrip("\n") + '''


# analogtv_load_ximage keeps a picture row's colours on the stack: two XColor
# rows, a mask and a table, about 17 KB on the board and 28 KB on the host, and
# the board's loop task has 16 KB. It overflowed on XAnalogTV's first picture
# load (a boot loop). The buffers come from the heap (PSRAM, being over 4 KB
# apiece in total) for the length of the call, and a failed allocation loads
# nothing.
OLD_LOAD_BUFFERS = """\\
  XColor col1[ANALOGTV_PIC_LEN];
  XColor col2[ANALOGTV_PIC_LEN];
  char mask[ANALOGTV_PIC_LEN];
  int multiq[ANALOGTV_PIC_LEN+4];
"""

NEW_LOAD_BUFFERS = """\\
  XColor *col1 = malloc(ANALOGTV_PIC_LEN * sizeof *col1);
  XColor *col2 = malloc(ANALOGTV_PIC_LEN * sizeof *col2);
  char *mask = malloc(ANALOGTV_PIC_LEN * sizeof *mask);
  int *multiq = malloc((ANALOGTV_PIC_LEN+4) * sizeof *multiq);
"""

OLD_LOAD_START = """\\
  img_w = pic_im->width;
  img_h = pic_im->height;
"""

NEW_LOAD_START = """\\
  if (!col1 || !col2 || !mask || !multiq) {
    free(col1);
    free(col2);
    free(mask);
    free(multiq);
    return 0;
  }

  img_w = pic_im->width;
  img_h = pic_im->height;
"""

OLD_LOAD_END = """\\
      input->signal[y-y_overscan+ANALOGTV_TOP+yoff][x+ANALOGTV_PIC_START+xoff] = composite;
    }
  }

  return 1;
}
"""

NEW_LOAD_END = """\\
      input->signal[y-y_overscan+ANALOGTV_TOP+yoff][x+ANALOGTV_PIC_START+xoff] = composite;
    }
  }

  free(col1);
  free(col2);
  free(mask);
  free(multiq);
  return 1;
}
"""


def heap_load_ximage_buffers(source: str) -> str:
    source = _replace_once(source, OLD_LOAD_BUFFERS, NEW_LOAD_BUFFERS)
    source = _replace_once(source, OLD_LOAD_START, NEW_LOAD_START)
    return _replace_once(source, OLD_LOAD_END, NEW_LOAD_END)
'''
