  (void)dpy;
  (void)cmap;
  const uint16_t p = px_swap((uint16_t)c->pixel);
  c->red = (unsigned short)(((p >> 11) & 0x1F) * 65535 / 31);
  c->green = (unsigned short)(((p >> 5) & 0x3F) * 65535 / 63);
  c->blue = (unsigned short)((p & 0x1F) * 65535 / 31);
'''
new = '''/* A channel of n bits widened to 16: value * 65535 / (2^n - 1). Looked up, not
 * divided, because analogtv asks for two colours a sample (about 250,000 a
 * picture) and the divides were most of the 150 ms that cost on the board. */
''' + fmt("k_expand5", t5) + fmt("k_expand6", t6) + '''
int XQueryColor(Display *dpy, Colormap cmap, XColor *c) {
  (void)dpy;
  (void)cmap;
  const uint16_t p = px_swap((uint16_t)c->pixel);
  c->red = k_expand5[(p >> 11) & 0x1F];
  c->green = k_expand6[(p >> 5) & 0x3F];
  c->blue = k_expand5[p & 0x1F];
'''
assert old in s; x.write_text(s.replace(old, new))
