from pathlib import Path
import re
fw = Path("firmware")
x = fw/"src/x11shim/xshim.c"; s = x.read_text()
a = s.index("/* A channel of n bits widened to 16")
b = s.index("int XQueryColor(Display *dpy")
tables = s[a:b]
s = s[:a] + s[b:]
old = '''  const uint16_t p = px_swap((uint16_t)c->pixel);
  c->red = k_expand5[(p >> 11) & 0x1F];
  c->green = k_expand6[(p >> 5) & 0x3F];
  c->blue = k_expand5[p & 0x1F];
  c->flags = DoRed | DoGreen | DoBlue;
  return 1;'''
new = '''  xshim_query_rgb565(c);
  return 1;'''
assert old in s; s = s.replace(old, new)
s = s.replace('#include "x11shim/pixmap.h"\n', '#include "x11shim/pixmap.h"\n#include "x11shim/query_color.h"\n', 1)
x.write_text(s)
tables = tables.replace("static const uint16_t", "static const uint16_t")
hdr = '''/* The colour of a pixel, for a hack that asks for a lot of them. Ours, not derived
 * from xscreensaver code.
 *
 * XQueryColor fills a colour's channels from its pixel. analogtv asks for two a
 * sample (about 250,000 a picture), so the call is inline here too: the same
 * function the shim's XQueryColor runs, for the one file that is built to use it
 * (hacks/analogtv_tv.c). The canvas holds each RGB565 pixel's bytes swapped. */
#ifndef XSHIM_QUERY_COLOR_H
#define XSHIM_QUERY_COLOR_H

#include <stdint.h>

#include "core/canvas.h"
#include "x11shim/xshim.h"

''' + tables.rstrip("\n") + '''

static inline void xshim_query_rgb565(XColor *c) {
  const uint16_t p = px_swap((uint16_t)c->pixel);
  c->red = k_expand5[(p >> 11) & 0x1F];
  c->green = k_expand6[(p >> 5) & 0x3F];
  c->blue = k_expand5[p & 0x1F];
  c->flags = DoRed | DoGreen | DoBlue;
}

#endif
'''
hdr = hdr.replace("static const uint16_t k_expand5", "static const uint16_t k_expand5")
(fw/"src/x11shim/query_color.h").write_text(hdr)
# wrapper
w = fw/"src/hacks/analogtv_tv.c"; t = w.read_text()
t = t.replace('#include "analogtv_tv.h"\n', '#include "analogtv_tv.h"\n#include "x11shim/query_color.h"\n', 1)
w.write_text(t)
# patch + tests
pa = Path("tools/analogtv_patch.py"); ps = pa.read_text()
ps = ps.replace('''      XQueryColor(it->dpy, it->colormap, &col1);
      XQueryColor(it->dpy, it->colormap, &col2);
''', '''      xshim_query_rgb565(&col1);
      xshim_query_rgb565(&col2);
''')
ps = ps.replace("# checks were 110 ms of that picture's cost.", "# checks were 110 ms of that picture's cost, and so were XQueryColor's calls\n# (the shim's inline xshim_query_rgb565 is the same function).")
pa.write_text(ps)
pt = Path("tools/tests/test_analogtv_patch.py"); u = pt.read_text()
u = u.replace('assert out.count("XQueryColor(") == 2\n    assert "XQueryColors" not in out', 'assert out.count("xshim_query_rgb565(") == 2\n    assert "XQueryColor" not in out')
old = '''        static void XQueryColors(void *d, int cm, XColor *c, int n) {
          for (int i = 0; i < n; i++) XQueryColor(d, cm, &c[i]);
        }'''
new = old + '''
        static void xshim_query_rgb565(XColor *c) { XQueryColor(0, 0, c); }'''
assert old in u; pt.write_text(u.replace(old, new))
EOF
