(fw/"src/x11shim/query_color.h").write_text(hdr)
# wrapper
w = fw/"src/hacks/analogtv_tv.c"; t = w.read_text()
t = t.replace('#include "analogtv_tv.h"\n', '#include "analogtv_tv.h"\n#include "x11shim/query_color.h"\n', 1)
w.write_text(t)
# patch + tests
pa = Path("tools/analogtv_patch.py"); ps = pa.read_text()
ps = ps.replace('''      XQueryColor(it->dpy, it->colormap, &col1);
      XQueryColor(it->dpy, it->colormap, &col2);
''', '''      xshim_query_rgb565(&col1);
      xshim_query_rgb565(&col2);
''')
ps = ps.replace("# checks were 110 ms of that picture's cost.", "# checks were 110 ms of that picture's cost, and so were XQueryColor's calls\n# (the shim's inline xshim_query_rgb565 is the same function).")
pa.write_text(ps)
pt = Path("tools/tests/test_analogtv_patch.py"); u = pt.read_text()
u = u.replace('assert out.count("XQueryColor(") == 2\n    assert "XQueryColors" not in out', 'assert out.count("xshim_query_rgb565(") == 2\n    assert "XQueryColor" not in out')
old = '''        static void XQueryColors(void *d, int cm, XColor *c, int n) {
          for (int i = 0; i < n; i++) XQueryColor(d, cm, &c[i]);
        }'''
new = old + '''
        static void xshim_query_rgb565(XColor *c) { XQueryColor(0, 0, c); }'''
assert old in u; pt.write_text(u.replace(old, new))
EOF
