import sys
from pathlib import Path

p = Path(sys.argv[1]) / "firmware/test/test_push_overlap/test_push_overlap.c"
s = p.read_text()
s = "#include <stdio.h>\n" + s
s = s.replace(
    "static void run_plain(const HackEntry *e, int frames, bool noise, uint32_t *out) {",
    "static uint16_t *g_keep;\nstatic void run_plain(const HackEntry *e, int frames, bool noise, uint32_t *out) {",
)
s = s.replace(
    "    out[f] = disc_hash(big.px);\n  }\n  runner_destroy(r);\n}",
    "    out[f] = disc_hash(big.px);\n    if (g_keep) memcpy(g_keep + (size_t)f * BW * BW, big.px, (size_t)BW * BW * 2);\n  }\n  runner_destroy(r);\n}",
    1,
)
old = """  uint32_t plain[FRAMES], noisy[FRAMES];
  run_plain(e, frames, false, plain);
  run_plain(e, frames, true, noisy);
"""
new = """  uint32_t plain[FRAMES], noisy[FRAMES];
  uint16_t *ka = malloc((size_t)FRAMES * BW * BW * 2), *kb = malloc((size_t)FRAMES * BW * BW * 2);
  g_keep = ka;
  run_plain(e, frames, false, plain);
  g_keep = kb;
  run_plain(e, frames, true, noisy);
  g_keep = NULL;
  int shown = 0, bad = 0;
  for (int f = 0; f < frames; f++) {
    if (plain[f] == noisy[f]) continue;
    bad++;
    if (shown++ > 5) continue;
    int n = 0, x0 = 999, x1 = -1, y0 = 999, y1 = -1, sx0, sx1;
    for (int y = 0; y < BW; y++) {
      if (!canvas_visible_span(&big, y, &sx0, &sx1)) continue;
      for (int x = sx0; x <= sx1; x++)
        if (ka[(size_t)f * BW * BW + y * BW + x] != kb[(size_t)f * BW * BW + y * BW + x]) {
          n++;
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
    }
    fprintf(stderr, "DIAG %s frame %d: %d px differ x %d..%d y %d..%d\\n", e->name, f, n, x0, x1, y0, y1);
  }
  fprintf(stderr, "DIAG %s total bad frames %d of %d\\n", e->name, bad, frames);
  free(ka);
  free(kb);
"""
assert s.count(old) == 1
p.write_text(s.replace(old, new))

